-- setvbuf changes buffering without losing what the buffer holds: data
-- waiting to be written, and data read ahead (issue #7). (Calling the C
-- library's setvbuf after I/O is undefined; Lua on Linux gives this too.)
local name = os.tmpname()
local f = io.open(name, "w")
f:write("abc")
f:setvbuf("no")
f:write("def")
f:setvbuf("full", 64)
f:write("ghi")
f:setvbuf("line")
f:write("jkl\n")
f:close()
f = io.open(name)
print(f:read(1))
f:setvbuf("no")
print(f:read(2))
f:setvbuf("full")
print(f:read("a"))
f:close()
os.remove(name)
